def low_stock(self, threshold: int) -> list[tuple[Product, int]]:
    """Active products with stock strictly below ``threshold``, lowest stock then SKU first."""
    levels = [(p, self._stock.get(p.sku)) for p in self.list_active()]
    below = [(p, on_hand) for p, on_hand in levels if on_hand < threshold]
    return sorted(below, key=lambda pair: (pair[1], pair[0].sku))

